#!/usr/bin/env python3
"""Dependency-free static generator. Defaults to the public, noindex approval preview."""
import argparse, json, html, shutil
from pathlib import Path
from urllib.parse import quote
ROOT=Path(__file__).resolve().parent
parser=argparse.ArgumentParser()
parser.add_argument('--base',default='/digiquality-preview/')
parser.add_argument('--origin',default='https://douglasopan.github.io')
parser.add_argument('--output',default='dist')
parser.add_argument('--production',action='store_true',help='Enable indexable production output ONLY after approval and content review.')
args=parser.parse_args()
BASE='/'+args.base.strip('/')+'/' if args.base.strip('/') else '/'
ORIGIN=args.origin.rstrip('/')
OUT=ROOT/args.output
OUT.mkdir(exist_ok=True,parents=True)
D=json.loads((ROOT/'src/content.json').read_text())
C=D['categories']; G=D['guides']; PAGES=[]
E=lambda s:html.escape(str(s),quote=True)
u=lambda path='':BASE+path.lstrip('/')
absolute=lambda path='':ORIGIN+u(path)
navitems=[('catalogo/','Componentes'),('recursos/','Recursos técnicos'),('empresa/','A Digiquality')]
icons=[
'<path d="M8 42h17m70 0h17"/><rect x="25" y="25" width="70" height="34" rx="3"/><path d="M37 25v34M83 25v34M38 42h8l5-7 8 14 8-14 7 7h9"/>',
'<path d="M15 27v34h90V27M28 61v12m64-12v12M25 27v17q0 11 11 11V27M95 27v17q0 11-11 11V27"/><path d="M41 34h38M41 44h38"/>',
'<circle cx="60" cy="31" r="22"/><path d="M48 51v23m24-23v23M49 32h22M54 21l12 22"/>',
'<circle cx="60" cy="32" r="23"/><path d="M48 52v22m24-22v22M41 38l39-14M47 25h26v15H47z"/>',
'<rect x="34" y="22" width="52" height="39" rx="2"/><path d="M46 61v18m14-18v18m14-18v18M45 22V7h30v15"/><circle cx="60" cy="15" r="4"/><path d="M46 38h29m-29 10h20"/>',
'<circle cx="60" cy="31" r="21"/><path d="M49 50v27m22-27v27M42 42l35-25M40 42h9M49 42v9"/>'
]
def icon(i,cl='card-illustration'):
 return f'<svg class="{cl}" viewBox="0 0 120 88" aria-hidden="true">{icons[i]}</svg>'
def brand(white=False):
 return f'<a class="brand" href="{u()}" aria-label="Digiquality, página inicial"><img src="{u("assets/logo-white.svg" if white else "assets/logo.svg")}" width="597" height="150" alt="Digiquality"></a>'
def header(active):
 links=''.join(f'<a href="{u(p)}"'+(' aria-current="page"' if active==p else '')+f'>{t}</a>' for p,t in navitems)
 preview='' if args.production else '<div class="preview"><span>PRÉVIA PARA APROVAÇÃO</span><span class="extra">Novo site Digiquality · </span>conteúdo sujeito a validação</div>'
 return f'<a class="skip" href="#conteudo">Pular para o conteúdo</a>{preview}<header class="header"><div class="wrap nav-row">{brand()}<button class="menu-toggle" aria-expanded="false" aria-controls="main-nav">Menu</button><nav id="main-nav" class="nav" aria-label="Navegação principal">{links}<a class="quote-link" href="{u("contato/")}"'+(' aria-current="page"' if active=='contato/' else '')+'>Solicitar cotação ↗</a></nav></div></header>'
def footer():
 return f'''<footer class="footer"><div class="wrap"><div class="footer-main"><div>{brand()}<p>Componentes eletrônicos para proteção, controle e medição.</p></div><div><h3>Explore</h3><ul><li><a href="{u('catalogo/')}">Componentes</a></li><li><a href="{u('recursos/')}">Recursos técnicos</a></li><li><a href="{u('empresa/')}">A Digiquality</a></li></ul></div><div><h3>Vamos conversar</h3><ul><li><a href="{u('contato/')}">Solicitar cotação</a></li><li><a href="mailto:vendas@digiquality.com.br">Contato comercial</a></li><li><a href="{u('sobre-esta-previa/')}">Sobre esta prévia</a></li></ul></div><div><h3>Contato comercial</h3><a class="footer-email" href="mailto:vendas@digiquality.com.br">vendas@digiquality.com.br</a><p>São Paulo · Brasil<br>Especificação e disponibilidade sob consulta.</p></div></div><div class="footer-bottom"><span>Digiquality · {'Site institucional' if args.production else 'Prévia de apresentação, outubro de 2026'}</span><span>Conteúdo técnico para consulta. Valide a aplicação no datasheet vigente.</span></div></div></footer>'''
def crumbs(items):
 return '<nav class="breadcrumb" aria-label="Você está em">'+f'<a href="{u()}">Início</a>'+''.join(f'<span aria-hidden="true">/</span><a href="{u(p)}">{E(t)}</a>' if p else f'<span aria-hidden="true">/</span><span aria-current="page">{E(t)}</span>' for t,p in items)+'</nav>'
def page(path,title,description,content,active='',breadcrumb=None,article=None,status404=False):
 canonical=absolute(path)
 schema=[{'@context':'https://schema.org','@type':'Organization','@id':ORIGIN+BASE+'#organization','name':'Digiquality','url':'http://www.digiquality.com.br/','email':'vendas@digiquality.com.br','logo':absolute('assets/logo.svg')}]
 if breadcrumb:
  elements=[{'@type':'ListItem','position':1,'name':'Início','item':absolute()}]
  for i,(t,p) in enumerate(breadcrumb,2): elements.append({'@type':'ListItem','position':i,'name':t,'item':absolute(p or path)})
  schema.append({'@context':'https://schema.org','@type':'BreadcrumbList','itemListElement':elements})
 if article:
  schema.append({'@context':'https://schema.org','@type':'Article','headline':article['title'],'dateModified':'2026-10-11','inLanguage':'pt-BR','mainEntityOfPage':canonical,'description':article['intro']})
 robots='noindex, follow' if not args.production or status404 else 'index, follow'
 fulltitle=title+' | Digiquality'
 doc=f'''<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{E(fulltitle)}</title><meta name="description" content="{E(description)}"><meta name="robots" content="{robots}"><meta name="theme-color" content="#008000"><meta name="referrer" content="strict-origin-when-cross-origin"><link rel="canonical" href="{canonical}"><link rel="icon" href="{u('assets/favicon.svg')}" type="image/svg+xml"><link rel="preload" href="{u('assets/manrope-latin.woff2')}" as="font" type="font/woff2" crossorigin><link rel="stylesheet" href="{u('assets/style.css')}"><meta property="og:type" content="{'article' if article else 'website'}"><meta property="og:locale" content="pt_BR"><meta property="og:site_name" content="Digiquality"><meta property="og:title" content="{E(fulltitle)}"><meta property="og:description" content="{E(description)}"><meta property="og:url" content="{canonical}"><meta property="og:image" content="{absolute('assets/social-preview.png')}"><meta property="og:image:width" content="1200"><meta property="og:image:height" content="630"><meta property="og:image:alt" content="Digiquality: componentes eletrônicos para proteção e controle"><meta name="twitter:card" content="summary_large_image">{''.join('<script type="application/ld+json">'+json.dumps(s,ensure_ascii=False).replace('</','<\\/')+'</script>' for s in schema)}<script src="{u('assets/app.js')}" defer></script></head><body>{header(active)}<main id="conteudo">{content}</main>{footer()}</body></html>'''
 target=OUT/'404.html' if status404 else OUT/path/'index.html'
 target.parent.mkdir(parents=True,exist_ok=True);target.write_text(doc,encoding='utf-8')
 if not status404:PAGES.append(path)
def catcards():
 return ''.join(f'''<a class="category-card" href="{u('produtos/'+c['slug']+'/')}" data-search="{E(c['search']+' '+c['title']+' '+' '.join(c['families']))}" data-function="{c['function']}"><div class="card-top"><span>0{i+1}</span><span>{E(c['sub'])}</span></div>{icon(i)}<h3>{E(c['short'])}</h3><p>{E(' · '.join(c['families'][:3]))}</p><div class="card-bottom"><span>Explorar componentes</span><span class="card-arrow" aria-hidden="true">↗</span></div></a>''' for i,c in enumerate(C))
def guidecards():
 return ''.join(f'''<article class="guide-card"><div class="meta">{E(g['tag'])} · leitura de {g['read']}</div><h3><a href="{u('guias/'+g['slug']+'/')}">{E(g['title'])}</a></h3><p>{E(g['intro'])}</p><a class="text-link" href="{u('guias/'+g['slug']+'/')}">Ler guia</a></article>''' for g in G)
def sources(items):
 return '<ul class="source-list">'+''.join(f'<li><a href="{E(url)}" target="_blank" rel="noopener noreferrer">{E(title)} ↗</a><small>{E(note)} · consultado em 11/10/2026</small></li>' for title,url,note in items)+'</ul>'
def cta():
 return f'<div class="cta-box"><div><h2>Já tem um código em mãos?</h2><p>Envie o part number, a quantidade e a aplicação.</p></div><a class="button arrow" href="{u("contato/")}">Solicitar cotação</a></div>'
def sidebar(category=None):
 cquery='?categoria='+quote(category['short']) if category else ''
 return f'''<aside class="sidebar"><span class="eyebrow">Próximo passo</span><h2>Vamos ao componente certo.</h2><p>Conte o que você precisa. Código, quantidade e aplicação ajudam a preparar a consulta.</p><a class="button arrow" href="{u('contato/')+cquery}">Solicitar cotação</a><hr><h3>Para ter em mãos</h3><ul><li>01 · Código e fabricante</li><li>02 · Quantidade necessária</li><li>03 · Aplicação e especificações</li><li>04 · Prazo desejado</li></ul><p class="no-margin">Disponibilidade, compatibilidade e condições comerciais precisam de confirmação.</p></aside>'''
# Home
page('', 'Componentes eletrônicos para proteção e controle', 'Explore fusíveis, PTC, TVS, MOV, SCR, TRIAC e sensores. Organize sua especificação e solicite cotação à Digiquality.', f'''
<div class="wrap hero"><div class="hero-copy"><div class="eyebrow">Componentes eletrônicos · Digiquality</div><h1>Proteção para cada ponto do <em>circuito.</em></h1><p class="lead">Fusíveis, semicondutores e sensores. Encontre a família certa para sua aplicação e dê o próximo passo com as especificações em mãos.</p><div class="actions"><a class="button arrow" href="{u('catalogo/')}">Explorar componentes</a><a class="button secondary" href="{u('contato/')}">Solicitar cotação</a></div><div class="micro">Proteção, controle e medição em um só lugar</div></div><div class="hero-art"><figure><img src="{u('assets/components.svg')}" alt="Ilustrações técnicas de um fusível de vidro, um varistor, um fusível automotivo e um semicondutor de potência" width="740" height="660" fetchpriority="high"><figcaption>Ilustrações de famílias de componentes. Modelos e disponibilidade sob consulta.</figcaption></figure></div></div>
<div class="topic-strip"><div class="wrap"><span>Sobrecorrente</span><span>Sobretensão</span><span>Controle de potência</span><span>Temperatura</span></div></div>
<section class="section wrap"><div class="section-head"><div><div class="eyebrow">Encontre por função</div><h2>Pequenos componentes.<br>Funções essenciais.</h2></div><p>Explore as famílias e os parâmetros que importam na seleção.</p></div><div class="catalog-grid">{catcards()}</div><p class="catalog-note">Catálogo por famílias. A presença de uma categoria não indica estoque ou disponibilidade imediata.</p></section>
<section class="section dark-section"><div class="wrap split-feature"><div><div class="eyebrow">Da especificação à consulta</div><h2>Uma boa cotação começa com a informação certa.</h2><p class="support">Para reposição ou projeto novo, organize os dados do componente antes de consultar.</p><a class="button light arrow" href="{u('contato/')}">Preparar minha cotação</a></div><div class="steps"><div class="step"><span class="step-num">01</span><div><h3>Identifique o componente</h3><p>Part number, fabricante e marcações. Se não tiver o código, descreva a função.</p></div></div><div class="step"><span class="step-num">02</span><div><h3>Conte como ele será usado</h3><p>Quantidade, aplicação, tensão, corrente, montagem e condições relevantes.</p></div></div><div class="step"><span class="step-num">03</span><div><h3>Confirme antes de decidir</h3><p>Especificação, disponibilidade, prazo e condições comerciais são avaliados na consulta.</p></div></div></div></div></section>
<section class="section wrap"><div class="section-head"><div><div class="eyebrow">Conhecimento que ajuda</div><h2>Mais clareza na seleção.</h2></div><a class="text-link" href="{u('recursos/')}">Todos os recursos</a></div><div class="guide-grid">{guidecards()}</div></section><section class="section compact wrap">{cta()}</section>''')
# Catalog
page('catalogo/','Catálogo de componentes eletrônicos','Busque famílias de componentes por nome, tecnologia ou função: fusíveis, porta-fusíveis, PTC, TVS, MOV, tiristores e NTC.',f'''<div class="wrap">{crumbs([('Componentes','')])}<div class="page-hero"><div class="eyebrow">Catálogo por famílias</div><h1>O componente começa pela função.</h1><p class="lead">Explore tecnologias de proteção, controle e medição. Use o nome ou a aplicação para encontrar a família.</p></div><section class="section compact"><div class="search-panel"><div class="field"><label for="catalog-search">Buscar componente ou tecnologia</label><input id="catalog-search" type="search" placeholder="Ex.: fusível 5x20, TVS, TRIAC, NTC…" autocomplete="off"></div><div class="field"><label for="catalog-filter">Filtrar por função</label><select id="catalog-filter"><option value="">Todas as funções</option value="sobrecorrente">Sobrecorrente</option><option value="sobretensao">Sobretensão</option><option value="conexao">Conexão e montagem</option><option value="controle">Controle de potência</option><option value="temperatura">Temperatura</option></select></div></div><p id="search-count" class="search-count" role="status" aria-live="polite">6 famílias de componentes para explorar.</p><div class="catalog-grid">{catcards()}</div><div id="empty-results" class="empty" hidden><h2>Nenhuma família encontrada.</h2><p>Tente uma tecnologia, como “fusível” ou “TVS”. Para um código específico, envie uma consulta comercial.</p><button class="button secondary" id="clear-search" type="button">Limpar busca</button> <a class="button" href="{u('contato/')}">Consultar meu código</a></div><p class="catalog-note">Esta busca explora famílias e tecnologias, não um banco de part numbers ou estoque. Código específico? <a href="{u('contato/')}" class="text-link">Solicite uma cotação</a></p><noscript><p class="notice">A busca interativa precisa de JavaScript. Todas as categorias continuam disponíveis abaixo.</p></noscript></section></div>''',active='catalogo/',breadcrumb=[('Componentes','')])
# Categories
for i,c in enumerate(C):
 items=[('Componentes','catalogo/'),(c['short'],'')]
 guide=next(g for g in G if g['slug']==c['guide'])
 content=f'''<div class="wrap">{crumbs(items)}<div class="page-hero category-intro"><div><div class="eyebrow">{E(c['sub'])}</div><h1>{E(c['title'])}</h1><p class="lead">{E(c['intro'])}</p></div><div class="category-visual">{icon(i,'')}<p>Representação esquemática ilustrativa da família</p></div></div><div class="content-grid section compact"><article><section><h2>O que faz</h2><p>{E(c['description'])}</p><div class="pills">{''.join('<span class="pill">'+E(f)+'</span>' for f in c['families'])}</div></section><section><h2>O que observar na seleção</h2><dl class="spec-grid">{''.join('<div class="spec-item"><dt>'+E(a)+'</dt><dd>'+E(b)+'</dd></div>' for a,b in c['params'])}</dl><p class="notice">A seleção exige validação no circuito e consulta ao datasheet vigente do código escolhido. Esta página é um ponto de partida, não uma aprovação de equivalência.</p></section><section class="faq"><h2>Dúvidas de seleção</h2>{''.join('<details><summary>'+E(q)+'</summary><p>'+E(a)+'</p></details>' for q,a in c['faqs'])}</section><section><h2>Documentação de referência</h2>{sources(c['sources'])}<p class="reading-meta">Referências técnicas externas. A menção a fabricantes não implica representação comercial atual ou disponibilidade.</p></section><section><div class="eyebrow">Continue explorando</div><h3><a href="{u('guias/'+guide['slug']+'/')}">{E(guide['title'])} ↗</a></h3><p>{E(guide['intro'])}</p></section></article>{sidebar(c)}</div></div>'''
 page('produtos/'+c['slug']+'/',c['title']+' | Seleção e cotação',c['intro'],content,active='catalogo/',breadcrumb=items)
# Resources
historical=[('Catálogo Littelfuse EC101-J','http://www.digiquality.com.br/pdf/EC101-J_v052505.pdf','Histórico · ©2005'),('Thyristor Product Catalog · Teccor','http://www.digiquality.com.br/pdf/Thyristors_Catalog.pdf','Histórico · ©2002'),('SIDACtor Data Book · Teccor','http://www.digiquality.com.br/pdf/Complete.pdf','Histórico · ©2002'),('NTC SP Series','http://www.digiquality.com.br/pdf/NTC_Thermistors_SP_Series.pdf','Histórico · data editorial não localizada; arquivo publicado até 2007'),('NTC TDC Series','http://www.digiquality.com.br/PDF/NTC_Thermistors_TDC_Series.pdf','Histórico · data editorial não localizada; arquivo publicado até 2007')]
page('recursos/','Guias e referências técnicas','Guias de seleção e links oficiais para documentação de fusíveis, TVS, MOV, tiristores e sensores. Materiais históricos identificados por data.',f'''<div class="wrap">{crumbs([('Recursos técnicos','')])}<div class="page-hero"><div class="eyebrow">Recursos técnicos</div><h1>Informação útil.<br>Seleção mais consciente.</h1><p class="lead">Guias objetivos e documentação de referência, com origem e data. Comece pela aplicação e confirme os detalhes na ficha do fabricante.</p></div><section class="section compact"><div class="guide-grid">{guidecards()}</div></section><section class="section compact"><div class="section-head"><div><div class="eyebrow">Fontes oficiais</div><h2>Biblioteca de referências.</h2></div><p>Links externos. Consulte sempre a revisão vigente do código específico.</p></div><div class="resource-list">{''.join(f'<div class="resource-row"><span class="index">0{i+1}</span><div><h3>{E(c["short"])}</h3><p>{E(c["sources"][0][2])}<br>Fonte: {E(c["sources"][0][0])} · consulta 11/10/2026</p></div><a class="text-link" href="{u("produtos/"+c["slug"]+"/#documentacao")}">Ver referências</a></div>' for i,c in enumerate(C))}</div></section><section class="section compact"><div class="section-head"><div><div class="eyebrow">Arquivo do site original</div><h2>Materiais históricos.</h2></div></div><p class="intro-note">Estes links preservam o acesso aos documentos do site original. As edições são antigas e não confirmam disponibilidade, condição comercial, certificação atual ou equivalência técnica. Arquivos hospedados no domínio legado usam HTTP.</p>{sources(historical)}</section><section class="section compact">{cta()}</section></div>''',active='recursos/',breadcrumb=[('Recursos técnicos','')])
# Guides
for g in G:
 items=[('Recursos técnicos','recursos/'),(g['title'],'')]
 related=next(c for c in C if c['slug']==g['related'])
 page('guias/'+g['slug']+'/',g['title'],g['intro'],f'''<div class="wrap">{crumbs(items)}<div class="page-hero article-title"><div class="eyebrow">Guia · {E(g['tag'])}</div><h1>{E(g['title'])}</h1><p class="lead">{E(g['intro'])}</p><p class="reading-meta">Revisão editorial: 11 de outubro de 2026 · Leitura de {g['read']}</p></div><div class="content-grid section compact"><article>{''.join('<section><h2>'+E(h)+'</h2><p>'+E(t)+'</p></section>' for h,t in g['sections'])}<section><h2>Fontes e leitura complementar</h2>{sources(g['sources'])}<p class="notice">Conteúdo informativo. A seleção do componente e qualquer substituição devem ser validadas por profissional responsável pelo projeto ou equipamento.</p></section><a class="text-link" href="{u('produtos/'+g['related']+'/')}">Explorar {E(related['short'])}</a></article>{sidebar(related)}</div></div>''',active='recursos/',breadcrumb=items,article=g)
# Company
page('empresa/','A Digiquality | Componentes eletrônicos','Conheça a Digiquality e suas famílias de componentes para proteção contra sobrecorrente, sobretensão, controle de potência e temperatura.',f'''<div class="wrap">{crumbs([('A Digiquality','')])}<div class="page-hero"><div class="eyebrow">A Digiquality</div><h1>Eletrônica no nome.<br>Componentes no foco.</h1><p class="lead">A Digiquality reúne famílias de componentes voltadas à proteção de circuitos, ao controle de potência e à medição de temperatura.</p></div><section class="section compact split-feature"><div><img src="{u('assets/components.svg')}" width="740" height="660" loading="lazy" alt="Estudo ilustrado de componentes para proteção e controle"><p class="reading-meta">Ilustrações de famílias; não representam estoque.</p></div><div><div class="company-block"><span>01</span><div><h2>Um foco técnico claro.</h2><p>Fusíveis e porta-fusíveis, PTC resetáveis, tecnologias de proteção contra sobretensão, tiristores e termistores fazem parte do universo apresentado pela Digiquality.</p></div></div><div class="company-block"><span>02</span><div><h2>A aplicação orienta a consulta.</h2><p>Corrente, tensão, temperatura, montagem e função são informações importantes para descrever uma necessidade. Um código completo e a quantidade tornam a cotação mais objetiva.</p></div></div><div class="company-block"><span>03</span><div><h2>Referências com contexto.</h2><p>Organizamos guias técnicos e documentos de fabricantes, diferenciando referências atuais de arquivos históricos. Condições comerciais e disponibilidade são confirmadas na consulta.</p></div></div></div></section><section class="section compact">{cta()}</section><p class="catalog-note">Apresentação baseada nas famílias publicadas no <a href="http://www.digiquality.com.br/" target="_blank" rel="noopener noreferrer">site original da Digiquality</a>, consultado em 11/10/2026. Dados institucionais adicionais serão incorporados após validação.</p><div style="height:45px"></div></div>''',active='empresa/',breadcrumb=[('A Digiquality','')])
# Contact
options=''.join('<option value="'+E(c['short'])+'">'+E(c['short'])+'</option>' for c in C)
page('contato/','Contato e cotação de componentes','Solicite cotação à Digiquality. Prepare código, quantidade, aplicação e prazo desejado e envie para vendas@digiquality.com.br.',f'''<div class="wrap">{crumbs([('Contato e cotação','')])}<div class="page-hero"><div class="eyebrow">Contato comercial</div><h1>Qual componente<br>você precisa?</h1><p class="lead">Comece pelo código, pela quantidade e pela aplicação. Prepare a mensagem aqui e envie pelo seu e-mail.</p></div><div class="contact-grid section compact"><div class="contact-details"><h2>Fale com a Digiquality.</h2><a class="big-email" href="mailto:vendas@digiquality.com.br">vendas@digiquality.com.br</a><dl><dt>Telefones publicados</dt><dd><a href="tel:+551142271482">(11) 4227-1482</a><br><a href="tel:+551126138823">(11) 2613-8823</a><br><a href="tel:+551126138824">(11) 2613-8824</a></dd><dt>O que enviar</dt><dd>Código e fabricante, quantidade, aplicação e prazo desejado. Para equivalências, inclua as especificações conhecidas.</dd></dl><p class="notice">Contatos publicados no site original, consultado em 11/10/2026. Operação atual e dados de atendimento ainda sujeitos a confirmação nesta prévia.</p><p class="catalog-note">Não há compra, pagamento ou confirmação automática de disponibilidade nesta página.</p></div><div class="form-wrap"><h2>Prepare sua cotação.</h2><p>Campos com * são obrigatórios. O formulário monta uma mensagem para você revisar e enviar.</p><form id="quote-form"><div class="form-grid"><div class="field full"><label for="part">Componente ou part number *</label><input id="part" name="part" required maxlength="180" placeholder="Código completo ou descrição do componente"></div><div class="field"><label for="quantity">Quantidade *</label><input id="quantity" name="quantity" required maxlength="60" placeholder="Ex.: 500 unidades"></div><div class="field"><label for="category">Família</label><select id="category" name="category"><option value="">Ainda não sei</option>{options}</select></div><div class="field full"><label for="application">Aplicação e especificações</label><textarea id="application" name="application" maxlength="1800" placeholder="Aplicação, tensão, corrente, dimensões e outros dados conhecidos"></textarea></div><div class="field full"><label for="deadline">Prazo desejado</label><input id="deadline" name="deadline" maxlength="120" placeholder="Quando você precisa do componente?"></div><div class="field"><label for="name">Seu nome *</label><input id="name" name="name" autocomplete="name" required maxlength="100"></div><div class="field"><label for="company">Empresa</label><input id="company" name="company" autocomplete="organization" maxlength="150"></div><div class="field full"><label for="email">E-mail para retorno *</label><input id="email" name="email" type="email" autocomplete="email" required maxlength="150"></div></div><div class="form-actions"><button id="prepare-quote" class="button arrow" type="submit" disabled>Preparar mensagem</button></div><p class="form-note">Os campos são processados apenas neste navegador. Esta página não armazena nem envia o formulário a um servidor. Ao usar seu aplicativo de e-mail, os dados serão enviados conforme o serviço que você utiliza. Não inclua senhas ou dados sensíveis.</p></form><div id="quote-output" class="output" hidden><label for="quote-message">Mensagem para revisar e copiar</label><textarea id="quote-message" readonly></textarea><p id="copy-status" class="output-status" role="status" aria-live="polite"></p><div class="form-actions"><a id="open-email" class="button arrow" href="mailto:vendas@digiquality.com.br">Abrir meu e-mail</a><button id="copy-message" class="button secondary" type="button">Copiar mensagem</button></div><p class="form-note">Se não houver um aplicativo de e-mail configurado, copie a mensagem e envie manualmente para vendas@digiquality.com.br.</p></div><noscript><p class="notice">Para montar a mensagem, ative JavaScript. Você também pode enviar código, quantidade e aplicação diretamente para vendas@digiquality.com.br.</p></noscript></div></div></div>''',active='contato/',breadcrumb=[('Contato e cotação','')])
# Preview disclosure
page('sobre-esta-previa/','Sobre esta prévia','Escopo e limitações da prévia pública para aprovação do novo site Digiquality.',f'''<div class="wrap">{crumbs([('Sobre esta prévia','')])}<div class="page-hero"><div class="eyebrow">Transparência</div><h1>Uma prévia para<br>avaliar com calma.</h1><p class="lead">Este endereço apresenta a proposta do novo site Digiquality antes de uma eventual migração para o domínio da empresa.</p></div><div class="content-grid section compact"><article><section><h2>O que esta versão oferece</h2><p>Navegação por famílias, guias técnicos, links de referência e preparação de uma solicitação de cotação por e-mail. Não há checkout, conta de cliente, estoque em tempo real ou envio automático de formulários.</p></section><section><h2>O que ainda precisa de validação</h2><p>Operação dos contatos, dados institucionais, portfólio comercial atual, disponibilidade e eventuais relações de representação. A direção visual mantém a proposta A da identidade; detalhes históricos da marca não são apresentados como fatos confirmados.</p></section><section><h2>Público, mas fora da busca</h2><p>Quem tiver o link pode abrir e compartilhar a prévia. As páginas solicitam aos buscadores compatíveis que não as indexem. Isso não é controle de acesso, e o código-fonte do repositório é público.</p></section><section><h2>Dados e recursos externos</h2><p>Não adicionamos analytics, rastreadores, cookies próprios ou serviços de formulário. Links de fabricantes, GitHub e seu provedor de e-mail operam sob suas próprias condições. O formulário usa somente memória temporária da página para preparar o texto.</p></section><section><h2>Antes da publicação definitiva</h2><p>Revisar informações com a empresa, validar o fluxo de atendimento e aprovar a migração. O domínio e a hospedagem atuais não foram alterados por esta prévia.</p></section></article>{sidebar()}</div></div>''',breadcrumb=[('Sobre esta prévia','')])
page('404.html','Página não encontrada','Esta página não foi encontrada na prévia da Digiquality.',f'<section class="section wrap"><div class="eyebrow">Erro 404</div><h1>Este caminho<br>não leva a um componente.</h1><p>Volte ao catálogo ou à página inicial para continuar.</p><div class="actions"><a class="button" href="{u("catalogo/")}">Explorar componentes</a><a class="button secondary" href="{u()}">Página inicial</a></div></section>',status404=True)
# Shared assets and deployment files
shutil.copytree(ROOT/'assets',OUT/'assets',dirs_exist_ok=True)
for name in ['style.css','app.js']: shutil.copy2(ROOT/'src'/name,OUT/'assets'/name)
# All category reference anchors, stable for deep links.
for f in OUT.glob('produtos/*/index.html'):
 text=f.read_text(); f.write_text(text.replace('<h2>Documentação de referência</h2>','<h2 id="documentacao">Documentação de referência</h2>'))
(OUT/'.nojekyll').write_text('')
# Project Pages robots.txt is below host root; meta robots is the actual preview control.
robots='# Preview: page-level noindex is authoritative. Crawling remains allowed so bots can read it.\nUser-agent: *\nAllow: /\n'
if args.production:robots+='Sitemap: '+absolute('sitemap.xml')+'\n'
(OUT/'robots.txt').write_text(robots)
sitemap='<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join('<url><loc>'+E(absolute(p))+'</loc><lastmod>2026-10-11</lastmod></url>' for p in PAGES)+'</urlset>\n'
(OUT/'sitemap.xml').write_text(sitemap)
(OUT/'site-manifest.json').write_text(json.dumps({'base':BASE,'origin':ORIGIN,'mode':'production' if args.production else 'approval-preview','indexable':args.production,'built':'2026-10-11','pages':PAGES},indent=2,ensure_ascii=False))
print(f'Built {len(PAGES)} pages + 404 in {OUT}, mode={"production" if args.production else "noindex preview"}')
